import{_ as i,l,o as t,c as n,v as r,p as d,x as e,d as o,i as h,S as s}from"./chunks/framework.InCnrqk-.js";const x=JSON.parse('{"title":"伊藤引理","description":"","frontmatter":{"title":"伊藤引理","date":"2026-09-10T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/ito-lemma.md","filePath":"quant/ito-lemma.md","lastUpdated":1789023840000}'),f={name:"quant/ito-lemma.md"};function _(p,a,c,E,u,B){const m=l("Mermaid");return t(),n("div",null,[a[1]||(a[1]=r('<h1 id="伊藤引理" tabindex="-1">伊藤引理 <a class="header-anchor" href="#伊藤引理" aria-label="Permalink to &quot;伊藤引理&quot;">​</a></h1><div class="epigraph"><p>对 $C^{2,1}$ 的 $f(t,W_t)$，二阶项 $\\partial_{ww}f\\,(\\mathrm d W)^2$ 不可忽略，它贡献 $\\tfrac12\\partial_{ww}f\\,\\mathrm d t$。</p><footer>—— 据 Itô, On Stochastic Differential Equations, Mem. Amer. Math. Soc., 1951；Karatzas and Shreve, 1991, 第 3 章整理</footer></div><p>上一课<a href="/quant/quadratic-variation">二次变差</a>给出乘法表 \\((\\mathrm d W)^2=\\mathrm d t\\)。缺口是：若状态是 \\(W\\) 的非线性函数，增量怎么写。经典链式法则丢掉二阶，会把 \\(\\ln S\\)、期权价格、贴现因子的漂移全部写错。本课只把 Itô 公式钉成后课 SDE 的微分引擎，不把积分构造重做一遍。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>设 \\(Y_t=f(t,W_t)\\)，\\(f\\) 对时间 \\(C^1\\)、对空间 \\(C^2\\)。普通微积分写 \\(\\mathrm d Y=f_t\\,\\mathrm d t+f_w\\,\\mathrm d W\\)。布朗路径上 \\((\\Delta W)^2\\) 与 \\(\\Delta t\\) 同阶，泰勒的二阶项在极限里活下来。漏掉它，\\(Y\\) 的漂移少一块 \\(\\tfrac12 f_{ww}\\)，后面几何布朗运动的显式解、Feynman–Kac 的生成元都会差一个二阶微分算子。</p><p>缺口不是「再解释一次二次变差」，而是把二次变差喂进多元泰勒，得到封闭的 \\(\\mathrm d f\\)。多维、带漂移的 \\(X\\) 是同一条公式的坐标替换，本课先写清一维布朗，再声明推广。</p><h3 id="伊藤不是把导数换成随机导数" tabindex="-1">伊藤不是把导数换成随机导数 <a class="header-anchor" href="#伊藤不是把导数换成随机导数" aria-label="Permalink to &quot;伊藤不是把导数换成随机导数&quot;">​</a></h3><p>\\(f_w\\) 仍是普通偏导，没有新的「路径导数」。随机性全部来自把 \\((\\mathrm d W)^2\\) 换成 \\(\\mathrm d t\\)，再取极限。Stratonovich 积分会把二阶项藏进对称极限，链式法则看起来像经典的；本序列主干用 Itô，因为 \\(\\int H\\,\\mathrm d W\\) 在可积条件下是鞅，定价要这条鞅性质。</p><p><span class="marginnote">金融里常把 \\(\\tfrac12\\sigma^2\\) 叫做凸性调整。来源就是 \\(f(x)=x^2\\) 或 \\(\\ln x\\) 的 \\(f&#39;&#39;\\)： Jensen 与 Itô 修正是同一块二阶。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>一维公式：</p> \\[\\mathrm d f(t,W_t)=\\Bigl(\\partial_t f+\\tfrac12\\partial_{ww}f\\Bigr)\\mathrm d t+\\partial_w f\\,\\mathrm d W_t. \\]<p>若 \\(X\\) 满足 \\(\\mathrm d X=\\mu\\,\\mathrm d t+\\sigma\\,\\mathrm d W\\)，则</p> \\[\\mathrm d f(t,X_t)=\\bigl(f_t+\\mu f_x+\\tfrac12\\sigma^2 f_{xx}\\bigr)\\mathrm d t+\\sigma f_x\\,\\mathrm d W_t. \\]<p>乘法规则仍是上一课的表：\\(\\mathrm d W\\cdot\\mathrm d t=0\\)。积分形式是定义；微分形式是简写。后课写 GBM、写期权价值过程，都直接套第二式。生成元 \\(\\mathcal A=\\mu\\partial_x+\\tfrac12\\sigma^2\\partial_{xx}\\) 会在 <a href="/quant/feynman-kac">Feynman–Kac</a> 再出现，本课只把它从 Itô 里读出来。</p>',15)),(t(),d(s,null,{default:e(()=>[h(m,{id:"mermaid-39",class:"mermaid",graph:"flowchart%20LR%0A%20%20TAYLOR%5B%22%E6%B3%B0%E5%8B%92%E5%88%B0%E4%BA%8C%E9%98%B6%22%5D%20--%3E%20QV%5B%22%E6%8A%8A%20dW%20%E5%B9%B3%E6%96%B9%E6%8D%A2%E6%88%90%20dt%22%5D%0A%20%20QV%20--%3E%20ITO%5B%22%E4%BC%8A%E8%97%A4%E5%85%AC%E5%BC%8F%22%5D%0A%20%20ITO%20--%3E%20GEN%5B%22%E7%94%9F%E6%88%90%E5%85%83%E5%87%BA%E7%8E%B0%E5%9C%A8%E6%BC%82%E7%A7%BB%E9%87%8C%22%5D%0A%20%20ITO%20--%3E%20SDE%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%EF%BC%9ASDE%20%E5%90%AB%E4%B9%89%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Itô 积分取左端点，增量 \\(\\Delta W\\) 与已经确定的 \\(f_w(t_i,W_{t_i})\\) 独立，一阶项期望为零，二阶项期望留下 \\(\\tfrac12 f_{ww}\\Delta t\\)。这就是漂移修正的概率来源。对凸函数 \\(f_{ww}\\gt 0\\)，Itô 漂移大于经典漂移——期权的时间价值、对数坐标里的 \\(-\\tfrac12\\sigma^2\\)，都是这块符号。</p><p>公式要求 \\(f\\) 足够光滑。弱解、局部时、Tanaka 公式处理 \\(|W|\\) 这类不够 \\(C^2\\) 的函数，主干定价用不到，不在本课。多维时交叉变差 \\([W^i,W^j]_t=\\rho_{ij}t\\) 进入混合二阶导；后课若写相关布朗，只加这一项。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证 Itô 公式（需要等距、局部化、停时），不引入 Stratonovich。跳扩散的 Itô 还要加 \\(\\Delta f-f_x\\Delta X\\) 的补偿，留给<a href="/quant/jump-process-intuition">跳过程直觉</a>。后课默认：对 \\(C^{2,1}\\) 函数可以直接写 Itô；SDE 的微分运算以本课第二式为准。下一课<a href="/quant/sde-meaning">随机微分方程的含义</a>回答 \\(\\mathrm d X=\\mu\\,\\mathrm d t+\\sigma\\,\\mathrm d W\\) 作为对象究竟是什么。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>伊藤引理 = 链式法则 + \\(\\tfrac12 f_{xx}\\,\\mathrm d[X]\\)。</li><li>修正项来自二次变差，不是新的导数概念。</li><li>主干用 Itô 是为了积分的鞅性质。</li><li>生成元 \\(\\mathcal A\\) 就是公式里的漂移算子。</li><li>出处：Itô, 1951；Karatzas–Shreve 第 3 章。</li></ul>',7))])}const q=i(f,[["render",_]]);export{x as __pageData,q as default};
